Q: How to open file in exclusive mode in C++ A: <p>Since C++17 there are two options:</p>
<ul>
<li>In C++23 by using the <a href="https://en.cppreference.com/w/cpp/io/ios_base/openmode" rel="nofollow noreferrer"><code>openmode</code></a> <code>std::ios::noreplace</code>.</li>
<li>In C++17 by using the <a href="https://en.cppreference.com/cpp/io/c/fopen" rel="nofollow noreferrer"><code>std::fopen</code></a> mode <code>x</code> (exclusive).<br />
Note: The <code>x</code> mode was added to <a href="/questions/tagged/c" class="s-tag post-tag" title="show questions tagged &#39;c&#39;" aria-label="show questions tagged &#39;c&#39;" rel="tag" aria-describedby="tag-c-tooltip-container" data-tag-menu-origin="Unknown">c</a> in C11.</li>
</ul>
<p>C++23 and later:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;cerrno&gt;
#include &lt;cstring&gt;
#include &lt;fstream&gt;
#include &lt;iostream&gt;

int main() {
    std::ofstream ofs(&quot;the_file&quot;, std::ios::noreplace);

    if (ofs) {
        std::cout &lt;&lt; &quot;success\n&quot;;
    } else {
        std::cerr &lt;&lt; &quot;Error: &quot; &lt;&lt; std::strerror(errno) &lt;&lt; '\n';
    }
}
</code></pre>
<p><a href="https://godbolt.org/z/MGn5hEhjE" rel="nofollow noreferrer">Demo</a></p>
<hr />
<p>C++17 and later:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;cerrno&gt;
#include &lt;cstdio&gt;
#include &lt;cstring&gt;
#include &lt;fstream&gt;
#include &lt;iostream&gt;
#include &lt;memory&gt;

struct FILE_closer {
    void operator()(std::FILE* fp) const { std::fclose(fp); }
};

// you may want overloads for `std::filesystem::path`, `std::string` etc too:
std::ofstream open_exclusively(const char* filename) {
    bool excl = [filename] {
        std::unique_ptr&lt;std::FILE, FILE_closer&gt; fp(std::fopen(filename, &quot;wx&quot;));
        return !!fp;
    }();
    auto saveerr = errno;

    std::ofstream stream;

    if (excl) {
        stream.open(filename);
    } else {
        stream.setstate(std::ios::failbit);
        errno = saveerr;
    } 
    return stream;
}
</code></pre>
<pre class="lang-cpp prettyprint-override"><code>int main() {
    std::ofstream ofs = open_exclusively(&quot;the_file&quot;);

    if (ofs) {
        std::cout &lt;&lt; &quot;success\n&quot;;
    } else {
        std::cout &lt;&lt; &quot;Error: &quot; &lt;&lt; std::strerror(errno) &lt;&lt; '\n';
    }
}
</code></pre>
<p><a href="https://godbolt.org/z/x6q6ea6qs" rel="nofollow noreferrer">Demo</a></p>
